     5→// Heap state
     6→static mut HEAP_START: *mut u8 = core::ptr::null_mut();
     7→static mut HEAP_END: *mut u8 = core::ptr::null_mut();
     8→static mut HEAP_CURRENT: *mut u8 = core::ptr::null_mut();
