    44→/// Reallocate memory.
    45→///
    46→/// # Safety
    47→/// If `ptr` is non-null, it must have been returned by a previous call to
    48→/// `malloc`, `realloc`, or `calloc`, and `size` must not exceed the original
    49→/// allocation size (this simple allocator doesn't track sizes).
    50→#[unsafe(no_mangle)]
    51→pub unsafe extern "C" fn realloc(ptr: *mut u8, size: usize) -> *mut u8 {
    52→    if ptr.is_null() {
    53→        return malloc(size);
    54→    }
    55→    let new_ptr = malloc(size);
    56→    if !new_ptr.is_null() {
    57→        unsafe { memcpy(new_ptr, ptr, size) };
    58→    }
    59→    new_ptr
    60→}
    61→
    62→#[unsafe(no_mangle)]
    63→pub extern "C" fn calloc(nmemb: usize, size: usize) -> *mut u8 {
    64→    let total = nmemb.saturating_mul(size);
    65→    let ptr = malloc(total);
    66→    if !ptr.is_null() {
    67→        // SAFETY: ptr points to at least total bytes (just allocated)
    68→        // Use memset directly to avoid compiler optimizing write_bytes -> memset
    69→        unsafe { memset(ptr, 0, total) };
    70→    }
    71→    ptr
    72→}
    73→
    74→#[unsafe(no_mangle)]
    75→pub extern "C" fn free(_ptr: *mut u8) {
    76→    // Bump allocator doesn't free individual allocations
    77→}
