    79→/// Allocate aligned memory.
    80→///
    81→/// # Safety
    82→/// `memptr` must point to valid writable memory for a pointer.
    83→#[unsafe(no_mangle)]
    84→pub unsafe extern "C" fn posix_memalign(
    85→    memptr: *mut *mut u8,
    86→    alignment: usize,
    87→    size: usize,
    88→) -> i32 {
    89→    // Simple implementation: over-allocate and align
    90→    if !alignment.is_power_of_two() || alignment < core::mem::size_of::<*mut u8>() {
    91→        return 22; // EINVAL
    92→    }
    93→    let ptr = malloc(size + alignment);
    94→    if ptr.is_null() {
    95→        return 12; // ENOMEM
    96→    }
    97→    let aligned = ((ptr as usize + alignment - 1) & !(alignment - 1)) as *mut u8;
    98→    unsafe {
    99→        *memptr = aligned;
   100→    }
   101→    0
   102→}
