   104→// Memory operations - must use manual loops, never core::ptr::* which LLVM optimizes to libc calls
   105→
   106→/// Copy memory.
   107→///
   108→/// # Safety
   109→/// `dest` must point to at least `n` bytes of writable memory.
   110→/// `src` must point to at least `n` bytes of readable memory.
   111→/// The memory regions must not overlap.
   112→#[unsafe(no_mangle)]
   113→pub unsafe extern "C" fn memcpy(dest: *mut u8, src: *const u8, n: usize) -> *mut u8 {
   114→    for i in 0..n {
   115→        unsafe { *dest.add(i) = *src.add(i) };
   116→    }
   117→    dest
   118→}
   119→
   120→/// Copy memory (handles overlapping regions).
   121→///
   122→/// # Safety
   123→/// `dest` must point to at least `n` bytes of writable memory.
   124→/// `src` must point to at least `n` bytes of readable memory.
   125→#[unsafe(no_mangle)]
   126→pub unsafe extern "C" fn memmove(dest: *mut u8, src: *const u8, n: usize) -> *mut u8 {
   127→    if (dest as usize) <= (src as usize) {
   128→        for i in 0..n {
   129→            unsafe { *dest.add(i) = *src.add(i) };
   130→        }
   131→    } else {
   132→        for i in (0..n).rev() {
   133→            unsafe { *dest.add(i) = *src.add(i) };
   134→        }
   135→    }
   136→    dest
   137→}
   138→
   139→/// Fill memory with a constant byte.
   140→///
   141→/// # Safety
   142→/// `dest` must point to at least `n` bytes of writable memory.
   143→#[unsafe(no_mangle)]
   144→pub unsafe extern "C" fn memset(dest: *mut u8, c: i32, n: usize) -> *mut u8 {
   145→    for i in 0..n {
   146→        unsafe { *dest.add(i) = c as u8 };
   147→    }
   148→    dest
   149→}
   150→
   151→/// Compare memory.
   152→///
   153→/// # Safety
   154→/// `s1` and `s2` must each point to at least `n` bytes of readable memory.
   155→#[unsafe(no_mangle)]
   156→pub unsafe extern "C" fn memcmp(s1: *const u8, s2: *const u8, n: usize) -> i32 {
   157→    for i in 0..n {
   158→        let a = unsafe { *s1.add(i) };
   159→        let b = unsafe { *s2.add(i) };
   160→        if a != b {
   161→            return a as i32 - b as i32;
   162→        }
   163→    }
   164→    0
   165→}
