     1→//! Thread-local storage and pthread stubs
     2→
     3→use crate::memory::{malloc, memset};
     4→use crate::syscall::{ARCH_SET_FS, SYS_ARCH_PRCTL, SYS_POLL, syscall2, syscall3};
     5→
     6→/// Initialize Thread-Local Storage
     7→///
     8→/// This sets up the FS segment register to point to a TLS block.
     9→/// Must be called before any code that uses #[thread_local] statics.
    10→pub fn init_tls() {
    11→    // For now, allocate a minimal TLS block
    12→    // The PT_TLS segment tells us the real size needed (24 bytes for our binary)
    13→    // We allocate: [TLS data (24 bytes)] [self-pointer (8 bytes)]
    14→    //                                     ^-- FS.base points here
    15→
    16→    const TLS_SIZE: usize = 64; // Over-allocate to be safe
    17→    const SELF_PTR_SIZE: usize = 8;
    18→
    19→    unsafe {
    20→        let block = malloc(TLS_SIZE + SELF_PTR_SIZE);
    21→        if block.is_null() {
    22→            return;
    23→        }
    24→
    25→        // Zero-initialize the TLS block (use our memset, not core::ptr::write_bytes)
    26→        // SAFETY: block points to TLS_SIZE + SELF_PTR_SIZE bytes just allocated
    27→        memset(block, 0, TLS_SIZE + SELF_PTR_SIZE);
    28→
    29→        // The self-pointer goes at the end, and FS.base points to it
    30→        let tcb = block.add(TLS_SIZE) as *mut usize;
    31→        *tcb = tcb as usize;
    32→
    33→        // Set FS.base to point at the self-pointer (TCB)
    34→        syscall2(SYS_ARCH_PRCTL, ARCH_SET_FS, tcb as u64);
    35→    }
    36→}
